"""Independent checks against the wallpaper's line-crossing color rule."""

import unittest

from src.component import calculate_black_area_doubled


def cell_area_doubled(x: int, y: int) -> int:
    """Sum the colors of the two half-cell triangles using exact arithmetic."""
    black_triangles = 0
    for offset in (1, 3):
        # Points (x + 1/4, y + 1/4) and (x + 3/4, y + 3/4)
        # sample both sides of any diagonal through the unit cell.
        x4, y4 = 4 * x + offset, 4 * y + offset
        crossings = x4 // 4 + y4 // 8 + (x4 + y4) // 8
        black_triangles += crossings % 2 == 0
    return black_triangles


class WallpaperGeometryTests(unittest.TestCase):
    def test_small_rectangles_against_geometry(self):
        for a in range(-6, 6):
            for c in range(a + 1, 7):
                for b in range(-6, 6):
                    for d in range(b + 1, 7):
                        expected = sum(
                            cell_area_doubled(x, y)
                            for x in range(a, c)
                            for y in range(b, d)
                        )
                        self.assertEqual(
                            calculate_black_area_doubled(a, b, c, d),
                            expected,
                            (a, b, c, d),
                        )

    def test_white_cell_below_origin(self):
        # There are no dividing lines inside this square; it is wholly white.
        self.assertEqual(calculate_black_area_doubled(-1, -1, 0, 0), 0)

    def test_coordinate_limits(self):
        self.assertEqual(
            calculate_black_area_doubled(-10**9, -10**9, 10**9, 10**9),
            4 * 10**18,
        )
        for x in (-10**9, 10**9 - 1):
            for y in (-10**9, 10**9 - 1):
                self.assertEqual(
                    calculate_black_area_doubled(x, y, x + 1, y + 1),
                    cell_area_doubled(x, y),
                )


if __name__ == '__main__':
    unittest.main()
